# Owner-supplied source list of 2026-11-04: Adams genealogy (1898), Hist. of the Mass. DAR (1905), Chase (1910),
# Booth (Historic Leaves 1, 1902), Historic Leaves 3 (1904), Loring (1852/55), Bi-centennial Book of Malden (1850),
# Boston Rare Maps (1797 survey), Medford Historical Commission (Edward Street Area), bouseblog (2015), DAR/WikiTree/Geni IDs.
ADG = lambda pg: f'Andrew N. Adams, <em>A Genealogical History of Henry Adams of Braintree, Mass., and His Descendants; also John Adams of Cambridge, Mass.</em> (1898), p. {pg}. <a href="https://archive.org/details/genealogicalh00adam/page/978/mode/1up?q=Tufts">Book scan (Internet Archive)</a>'
MDAR = '<em>History of the Massachusetts Daughters of the American Revolution</em> (1905), &ldquo;Anne Adams Tufts Chapter, of Somerville,&rdquo; beginning p. 5. <a href="https://archive.org/details/historyofmassach00daug">Book scan (Internet Archive)</a>'
CHS = lambda v, pg: f'Ellen Chase, <em>The Beginnings of the American Revolution</em> (1910), vol. {"I II III".split()[v-1]}, p. {pg}. <a href="https://archive.org/details/beginningsrevo0{v}chasrich/page/{pg}/mode/1up">Page (Internet Archive)</a>'
HL3 = '<em>Historic Leaves</em> (Somerville Historical Society), vol. 3 (1904&ndash;05), &ldquo;Charlestown Schools&hellip;,&rdquo; p. 89. <a href="https://www.perseus.tufts.edu/hopper/text?doc=Perseus%3Atext%3A2001.05.0303%3Achapter%3D14%3Apage%3D89">Text (Perseus)</a>'
LOR = 'James Spear Loring, <em>The Hundred Boston Orators</em> (1855 ed.), p. 186. <a href="https://archive.org/details/hundredbostonora00lori">Book scan (Internet Archive)</a>'
MAL = lambda pg: f'<em>The Bi-centennial Book of Malden</em> (1850), p. {pg}. <a href="https://archive.org/details/bicentennialbook00bost">Book scan (Internet Archive)</a>'
BRM97 = '&ldquo;18th-century Peter Tufts, Jr. survey of a road from Concord to Cambridge, Mass.,&rdquo; Boston Rare Maps, inventory BRM3348. <a href="https://bostonraremaps.com/inventory/peter-tufts-survey-concord-cambridge-1797/">Dealer description</a>'
BOUSE = 'Somerville history blog (bouseblog), &ldquo;Magoun Square&rdquo; (August 6, 2015). <a href="https://bouseblog.wordpress.com/2015/08/06/magoun-square/">Article</a>'
MHC = 'Medford Historical Commission, Inventory Form A, &ldquo;Edward Street Area&rdquo; (2022). <a href="https://medfordhistoricalcommission.org/wp-content/uploads/2022/02/area-edward.pdf">PDF</a>'
